// 管理后台访问密码配置
// ---------------------------------------------------------------------------
// 这是"挡住随手点进来的人"的前端密码，明文存放，查看源码即可见。
// 有意如此取舍：真正的安全边界是 GitHub Token 权限，没有 Token 改不了任何内容。
// 换密码：直接改下面的 pass 值，保存 → 用 GitHub Desktop 提交推送即可。
// ⚠️ 上线前务必改成你自己的密码，admin123 仅是演示值！
// ---------------------------------------------------------------------------
window.ADMIN_LOCK = {
  enabled: true,
  // 明文密码：本文件随网站公开，懂技术的人看源码即可见（有意取舍，真正安全靠 Token）
  pass: 'admin123', // ← 改这里即可换密码（上线必改）
  days: 30, // 解锁后在本设备记住多少天
};

// 正文（slug=hello-world，由发文bot/管理后台维护；手改这个文件前台直接生效）
window.POST_CONTENT = window.POST_CONTENT || {};
window.POST_CONTENT["hello-world"] = {"content":"<h2>你好，世界</h2><p>这是模板自带的演示文章。用微信 bot 或管理后台发布第一篇真实文章后，可以删除本篇。</p><p>本站数据层支持两种模式：仓库静态数据（开箱即用）与 Cloudflare D1 权威数据源（见 docs/SETUP.md）。</p>"};

// 观影天索引 2026 年（发布时自动重算，勿手改）
window.WATCH_DAYS = window.WATCH_DAYS || {};
Object.assign(window.WATCH_DAYS, {"2026-11-03":{"m":1,"t":0,"p":""}});

// 友链数据（由管理后台维护，也可直接编辑）
// 格式：{ name: "站名", url: "https://…", desc: "一句话介绍", avatar: "头像图链接（可省略）" }
window.FRIEND_LINKS = [{"name":"示例博客","url":"https://example.com","desc":"一个示例友链","avatar":""}];

// 瞬间数据 2026 年卷（由管理后台/发文bot维护）
window.MOMENTS_PARTS = window.MOMENTS_PARTS || {};
window.MOMENTS_PARTS["2026"] = [{"date":"2026/11/03 12:00:00","content":"<p>第一条演示瞬间，发一条真实的替换它吧。</p>","type":"note","kind":"note","title":"","runtime":0,"poster":""}];

// TMDB API Key（"君子设置"：随站点公开，仅用于电影搜索/时长查询，泄露无害）
// 申请：themoviedb.org → 头像 → Settings → API
window.TMDB_KEY = '';
